     1	/**
     2	 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
     3	 *
     4	 * Must call (do not reimplement): indexIssue, indexComment, indexProject
     5	 */
     6	import { createLogger } from "@/lib/logger";
     7	import * as commentRepo from "@/server/repositories/comment-repository";
     8	import * as issueRepo from "@/server/repositories/issue-repository";
     9	import * as projectRepo from "@/server/repositories/project-repository";
    10	import {
    11	  indexComment,
    12	  indexIssue,
    13	  indexProject,
    14	} from "@/server/services/search-service";
    15	import { runJob } from "./types";
    16	import type { JobResult } from "@/server/jobs/types";
    17	import type { OrgId } from "@/types/common";
    18	
    19	/** Rows read per page while walking the org's content. */
    20	const PAGE_SIZE = 100;
    21	
    22	const logger = createLogger("search-reindex-job");
    23	
    24	/**
    25	 * Walks one tenant's live projects, issues and comments and re-upserts every
    26	 * document. Scoped to a single org on purpose: a full-fleet reindex is a
    27	 * sequence of these, so one slow tenant cannot stall the rest.
    28	 */
    29	export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
    30	  return runJob("search-reindex", async (result) => {
    31	    const projects = await projectRepo.listProjects({
    32	      orgId,
    33	      limit: PAGE_SIZE,
    34	      cursor: null,
    35	    });
    36	
    37	    for (const project of projects.items) {
    38	      try {
    39	        await indexProject(orgId, project);
    40	        result.processed += 1;
    41	      } catch (error) {
    42	        result.failed += 1;
    43	        logger.error("failed to index project", {
    44	          projectId: project.id,
    45	          reason: error instanceof Error ? error.message : String(error),
    46	        });
    47	      }
    48	    }
    49	
    50	    const issues = await issueRepo.listIssues({
    51	      orgId,
    52	      limit: PAGE_SIZE,
    53	      cursor: null,
    54	    });
    55	
    56	    for (const issue of issues.items) {
    57	      try {
    58	        await indexIssue(orgId, issue);
    59	        result.processed += 1;
    60	
    61	        const comments = await commentRepo.listComments({
    62	          orgId,
    63	          issueId: issue.id,
    64	          includeArchived: false,
    65	          limit: PAGE_SIZE,
    66	          cursor: null,
    67	        });
    68	
    69	        for (const comment of comments.items) {
    70	          await indexComment(orgId, comment);
    71	          result.processed += 1;
    72	        }
    73	      } catch (error) {
    74	        result.failed += 1;
    75	        logger.error("failed to index issue", {
    76	          issueId: issue.id,
    77	          reason: error instanceof Error ? error.message : String(error),
    78	        });
    79	      }
    80	    }
    81	  });
    82	}
