    16	import { searchQuerySchema } from "@/schemas/search";
    17	import { buildFlagContext } from "@/server/services/feature-flag-service";
    18	import { getOrganizationSummary } from "@/server/services/organization-service";
    19	import { search } from "@/server/services/search-service";
    20	
    21	export const dynamic = "force-dynamic";
    22	
    23	const PALETTE_LIMIT = 10;
    24	
    25	export async function GET(request: Request): Promise<Response> {
    26	  try {
    27	    const url = new URL(request.url);
    28	    const orgSlug = url.searchParams.get("orgSlug");
    29	    const q = url.searchParams.get("q");
    30	
    31	    if (orgSlug === null || q === null) {
    32	      return failure("validation_failed", "orgSlug and q are required.");
    33	    }
    34	
    35	    const actor = await getActor(orgSlug);
    36	
    37	    if (!can(actor, "org:read", { kind: "organization", orgId: actor.orgId })) {
    38	      return failure("forbidden", "You cannot search this organization.");
    39	    }
    40	
    41	    const { organization } = await getOrganizationSummary(actor, actor.orgId);
    42	    const context = buildFlagContext(actor, organization);
    43	
    44	    if (!isEnabled("command_palette", context)) {
    45	      return failure("forbidden", "The command palette is not enabled here.");
    46	    }
    47	
    48	    const parsed = searchQuerySchema.safeParse({
    49	      orgId: actor.orgId,
    50	      q,
    51	      kinds: isEnabled("advanced_search", context)
    52	        ? ["issue", "comment", "project"]
    53	        : ["issue"],
    54	      limit: PALETTE_LIMIT,
    55	    });
    56	    if (!parsed.success) {
    57	      return failure("validation_failed", "Bad search query.");
    58	    }
    59	
    60	    const page = await search(actor, parsed.data);
    61	    return Response.json({ items: page.items, total: page.total });
    62	  } catch (error) {
    63	    return errorResponse(error);
    64	  }
    65	}
