     1	"use server";
     2	
     3	/**
     4	 * Updates issue fields.
     5	 *
     6	 * Owner D. Only the fields present in the payload are touched; the service
     7	 * diffs them and emits `issue.updated` with `changedFields` so the activity log
     8	 * can describe the edit without re-reading the row.
     9	 *
    10	 * Must call (do not reimplement): updateIssueSchema, can, getActor,
    11	 * toActionResult
    12	 */
    13	
    14	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
    15	import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
    16	import { withAction } from "@/actions/_lib/with-action";
    17	import { CACHE_PROFILES, issueTag, revalidateTagged } from "@/lib/cache";
    18	import { can } from "@/lib/permissions";
    19	import { updateIssueSchema, type UpdateIssueInput } from "@/schemas/issue";
    20	import { updateIssue } from "@/server/services/issue-service";
    21	import type { ActionResult } from "@/types/api";
    22	import type { Issue } from "@/types/issue";
    23	
    24	const run = withAction<typeof updateIssueSchema, Issue>(
    25	  updateIssueSchema,
    26	  async (raw, actor) => {
    27	    const input = raw as UpdateIssueInput;
    28	
    29	    const allowed = can(actor, "issue:update", {
    30	      kind: "issue",
    31	      orgId: input.orgId,
    32	      projectId: PENDING_PROJECT_ID,
    33	      issueId: input.issueId,
    34	      authorId: actor.userId,
    35	      assigneeId: actor.userId,
    36	    });
    37	    if (!allowed) {
    38	      throw new ForbiddenActionError("issue:update");
    39	    }
    40	
    41	    const issue = await updateIssue(actor, input);
    42	    revalidateTagged([issueTag(issue.id)], CACHE_PROFILES.seconds);
    43	    return issue;
    44	  },
    45	  { revalidate: ["issues"], cacheProfile: "seconds" },
    46	);
    47	
    48	export async function updateIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
    49	  return run(raw);
    50	}

