     1	/**
     2	 * Next.js instrumentation hook. Runs once per server process before any
     3	 * request is handled — the only sanctioned place to register the event-bus
     4	 * subscribers and start the in-process job scheduler.
     5	 */
     6	export async function register(): Promise<void> {
     7	  if (process.env.NEXT_RUNTIME !== "nodejs") return;
     8	
     9	  const { registerEventHandlers } = await import(
    10	    "@/server/services/event-registry"
    11	  );
    12	  const { startScheduler } = await import("@/server/jobs/scheduler");
    13	
    14	  registerEventHandlers();
    15	  startScheduler();
    16	}
    17	
    18	export function onRequestError(
    19	  error: unknown,
    20	  request: { path: string; method: string },
    21	): void {
    22	  console.error(
    23	    `[taskflow] ${request.method} ${request.path} failed:`,
    24	    error instanceof Error ? error.message : error,
    25	  );
    26	}
