     1	/**
     2	 * Barrel for the service layer; Server Actions import from here.
     3	 *
     4	 * Each service is exposed as a namespace so a call site reads
     5	 * `issueService.createIssue(actor, input)` — the actor-first convention stays
     6	 * visible, and two services may share a method name without colliding.
     7	 */
     8	export * as activityService from "./activity-service";
     9	export * as attachmentService from "./attachment-service";
    10	export * as authService from "./auth-service";
    11	export * as billingService from "./billing-service";
    12	export * as commentService from "./comment-service";
    13	export * as digestService from "./digest-service";
    14	export * as emailService from "./email-service";
    15	export * as featureFlagService from "./feature-flag-service";
    16	export * as invitationService from "./invitation-service";
    17	export * as issueService from "./issue-service";
    18	export * as labelService from "./label-service";
    19	export * as memberService from "./member-service";
    20	export * as notificationService from "./notification-service";
    21	export * as organizationService from "./organization-service";
    22	export * as projectService from "./project-service";
    23	export * as searchService from "./search-service";
    24	export * as sessionService from "./session-service";
    25	export * as usageService from "./usage-service";
    26	export * as webhookService from "./webhook-service";
    27	
    28	export {
    29	  registerEventHandlers,
    30	  unregisterEventHandlers,
    31	} from "./event-registry";
    32	
    33	export type { ActivityRecordInput } from "./activity-service";
    34	export type {
    35	  EmailTemplate,
    36	  OutgoingEmail,
    37	  RenderedEmail,
    38	} from "./email-service";
    39	export type { NotificationPayload } from "./notification-service";
    40	export type { SearchHit } from "./search-service";
----
     1	/**
     2	 * Private helpers shared by the service layer.
     3	 *
     4	 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
     5	 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
     6	 * Neither re-implements a cross-cutting concern — they are adapters onto
     7	 * `@/lib/permissions` and `@/lib/event-bus`.
     8	 */
     9	import { toIsoTimestamp } from "@/types/common";
    10	import type { Comment } from "@/types/comment";
    11	import type { OrgId, UserId } from "@/types/common";
    12	import type { EventEnvelope } from "@/types/event";
    13	import type { Issue } from "@/types/issue";
    14	import type { Actor, Member } from "@/types/member";
    15	import type { PermissionResource } from "@/types/permission";
    16	import type { Project } from "@/types/project";
    17	import type { WebhookId } from "@/types/common";
    18	
    19	/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
    20	export class NotFoundError extends Error {
    21	  readonly code = "not_found" as const;
    22	
    23	  constructor(
    24	    readonly entity: string,
    25	    readonly id: string,
    26	  ) {
    27	    super(`${entity} ${id} was not found`);
    28	    this.name = "NotFoundError";
    29	  }
    30	}
    31	
    32	/** Unwraps a repository read, turning the `null` case into a domain error. */
    33	export function requireFound<T>(
    34	  value: T | null | undefined,
    35	  entity: string,
    36	  id: string,
    37	): T {
    38	  if (value === null || value === undefined) {
    39	    throw new NotFoundError(entity, id);
    40	  }
    41	  return value;
    42	}
    43	
    44	export function orgResource(orgId: OrgId): PermissionResource {
    45	  return { kind: "organization", orgId };
    46	}
    47	
    48	export function billingResource(orgId: OrgId): PermissionResource {
    49	  return { kind: "billing", orgId };
    50	}
    51	
    52	export function activityResource(orgId: OrgId): PermissionResource {
    53	  return { kind: "activity", orgId };
    54	}
    55	
    56	export function notificationResource(
    57	  orgId: OrgId,
    58	  recipientId: UserId,
    59	): PermissionResource {
    60	  return { kind: "notification", orgId, recipientId };
    61	}
    62	
    63	export function webhookResource(
    64	  orgId: OrgId,
