     1	/**
     2	 * Token-bucket limiter applied to invites, comments, search and password
     3	 * resets.
     4	 *
     5	 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
     6	 * runs single-writer, and the corpus has no external cache. Capacity scales
     7	 * with the org's plan through `getPlanLimits()`, so a growth org is not held
     8	 * to a free org's ceiling; the per-bucket shape below is the base rate.
     9	 */
    10	import { getPlanLimits } from "@/config/plan-limits";
    11	import type { PlanId } from "@/types/billing";
    12	import type { IsoTimestamp, OrgId } from "@/types/common";
    13	import { toIsoTimestamp } from "@/types/common";
    14	
    15	export type RateLimitVerdict = {
    16	  allowed: boolean;
    17	  remaining: number;
    18	  resetAt: IsoTimestamp;
    19	};
    20	
    21	export type RateLimitConfig = { capacity: number; refillPerMinute: number };
    22	
    23	export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
    24	  "member:invite": { capacity: 20, refillPerMinute: 2 },
    25	  "comment:create": { capacity: 60, refillPerMinute: 20 },
    26	  "issue:create": { capacity: 60, refillPerMinute: 20 },
    27	  "search:query": { capacity: 120, refillPerMinute: 60 },
    28	  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
    29	  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
    30	};
    31	
    32	/** Applied to any key not in the table above. */
    33	const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };
    34	
    35	type BucketState = { tokens: number; updatedAt: number };
    36	
    37	const buckets = new Map<string, BucketState>();
    38	
    39	/** Plan-aware org context; services set this when they know the org's plan. */
    40	const planByOrg = new Map<OrgId, PlanId>();
    41	
    42	/** Records an org's plan so subsequent bucket sizes scale with its quota. */
    43	export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
    44	  planByOrg.set(orgId, plan);
    45	}
    46	
    47	export function getBucketConfig(bucketKey: string): RateLimitConfig {
    48	  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
    49	}
    50	
    51	/**
    52	 * Scales the base bucket by the org's hourly API allowance, so the limiter
    53	 * and the plan catalogue can never drift apart: the plan is the source of
    54	 * the ceiling, this table only sets the relative shape.
    55	 */
    56	function configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {
    57	  const base = getBucketConfig(bucketKey);
    58	  const plan = planByOrg.get(orgId) ?? "free";
    59	  const hourly = getPlanLimits(plan).apiRequestsPerHour;
    60	  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;
    61	
    62	  return {
    63	    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    64	    refillPerMinute: Math.min(
    65	      base.refillPerMinute * factor,
    66	      base.refillPerMinute * 100,
    67	    ),
    68	  };
    69	}
    70	
    71	/**
    72	 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
    73	 * Async because the production limiter is expected to move behind a store —
    74	 * every call site already awaits it.
    75	 */
    76	export async function consumeRateLimit(
    77	  orgId: OrgId,
    78	  bucketKey: string,
    79	  cost = 1,
    80	): Promise<RateLimitVerdict> {
    81	  const config = configFor(orgId, bucketKey);
    82	  const key = `${orgId}:${bucketKey}`;
    83	  const nowMs = Date.now();
    84	
    85	  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
    86	  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
    87	  const tokens = Math.min(
    88	    config.capacity,
    89	    state.tokens + elapsedMinutes * config.refillPerMinute,
    90	  );
    91	
    92	  const allowed = tokens >= cost;
    93	  const remaining = allowed ? tokens - cost : tokens;
    94	  buckets.set(key, { tokens: remaining, updatedAt: nowMs });
    95	
    96	  const deficit = allowed ? config.capacity - remaining : cost - remaining;
    97	  const minutesToReset =
    98	    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;
    99	
   100	  return {
   101	    allowed,
   102	    remaining: Math.floor(remaining),
   103	    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
   104	  };
   105	}
   106	
   107	/** Test-only: drops every bucket and org plan association. */
   108	export function resetRateLimits(): void {
   109	  buckets.clear();
   110	  planByOrg.clear();
   111	}
