     1	/**
     2	 * Full-page search results.
     3	 *
     4	 * Owner D. The command palette and this page share one action, so the flag
     5	 * check has to live in both places — the palette narrows what it asks for, and
     6	 * this page explains why comments are missing from the results.
     7	 *
     8	 * Must call (do not reimplement): isEnabled
     9	 */
    10	
    11	import Link from "next/link";
    12	import type { Metadata } from "next";
    13	import { EmptyState } from "@/components/ui/empty-state";
    14	import { isEnabled } from "@/lib/feature-flags";
    15	import { searchQuerySchema } from "@/schemas/search";
    16	import { buildFlagContext } from "@/server/services/feature-flag-service";
    17	import { search as runSearch } from "@/server/services/search-service";
    18	import { loadTenantContext } from "../_lib/tenant-context";
    19	
    20	type PageParams = { orgSlug: string };
    21	
    22	export const dynamic = "force-dynamic";
    23	
    24	export const metadata: Metadata = {
    25	  title: "Search",
    26	};
    27	
    28	const RESULT_LIMIT = 30;
    29	
    30	export default async function Page(props: {
    31	  params: Promise<PageParams>;
    32	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    33	}) {
    34	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    35	  const { orgSlug } = await props.params;
    36	  const search = await props.searchParams;
    37	
    38	  const { org, actor } = await loadTenantContext(orgSlug);
    39	
    40	  const advanced = isEnabled("advanced_search", buildFlagContext(actor, org));
    41	  const query = typeof search.q === "string" ? search.q : "";
    42	
    43	  if (query.length === 0) {
    44	    return (
    45	      <div className="space-y-8">
    46	        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
    47	        <EmptyState
    48	          title="Search this organization"
    49	          description="Type at least one character to look through issues, and — on the higher plans — comments and projects too."
    50	        />
    51	      </div>
    52	    );
    53	  }
    54	
    55	  const parsed = searchQuerySchema.safeParse({
    56	    orgId: org.id,
    57	    q: query,
    58	    kinds: advanced ? ["issue", "comment", "project"] : ["issue"],
    59	    limit: RESULT_LIMIT,
    60	  });
    61	
    62	  if (!parsed.success) {
    63	    return (
    64	      <div className="space-y-8">
    65	        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
    66	        <EmptyState title="That query is not valid" description="Try something shorter." />
    67	      </div>
    68	    );
    69	  }
    70	
    71	  const page = await runSearch(actor, parsed.data);
    72	
    73	  return (
    74	    <div className="space-y-8">
    75	      <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
    76	
    77	      {page.items.length === 0 ? (
    78	        <EmptyState title={`Nothing matches “${query}”`} />
    79	      ) : (
    80	        <ul className="space-y-4">
    81	          {page.items.map((hit) => (
    82	            <li key={`${hit.kind}:${hit.id}`}>
    83	              <Link href={hit.href} className="block">
    84	                <span className="text-xs uppercase tracking-wide text-slate-400">
    85	                  {hit.kind}
    86	                </span>
    87	                <span className="mt-0.5 block text-sm font-medium">
    88	                  {hit.title}
    89	                </span>
    90	                <span className="mt-0.5 block text-sm text-slate-600">
    91	                  {hit.snippet}
    92	                </span>
    93	              </Link>
    94	            </li>
    95	          ))}
    96	        </ul>
    97	      )}
    98	    </div>
    99	  );
   100	}
