   109	      <h1 className="text-2xl font-semibold tracking-tight">Search</h1>
   110	      <form action={`/${props.orgSlug}/search`} className="mt-4 max-w-md">
   111	        <input
   112	          name="q"
   113	          type="search"
   114	          defaultValue={props.query}
   115	          placeholder="Search issues…"
   116	          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
   117	        />
   118	      </form>
   119	      {!props.advanced ? (
   120	        <p className="mt-2 text-xs text-slate-500">
